import test from 'node:test';
import assert from 'node:assert';
import { createState, frame, collides, WIDTH, HEIGHT, BRICK_W, BRICK_H, BRICK_TOP, BRICK_GAP, BRICK_COLS } from '../game/neon.js';

const mockCtx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  font: () => {},
  fillText: () => {}
};

test('D1: Ball should bounce off a brick (currently plows through)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y + BRICK_H + 2;
  state.ball.vx = 0;
  state.ball.vy = -100; // Moving UP

  frame(mockCtx, state);

  assert.strictEqual(brick.alive, false);
  assert.ok(state.ball.vy > 0, 'Ball should have bounced DOWN');
});

test('D2: Ball should bounce off the SIDE of a brick (discriminate naive vy flip)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Ball hits the left side of the brick moving RIGHT
  state.ball.x = brick.x - 2;
  state.ball.y = brick.y + BRICK_H / 2;
  state.ball.vx = 100;
  state.ball.vy = 0;

  frame(mockCtx, state);

  assert.strictEqual(brick.alive, false);
  assert.ok(state.ball.vx < 0, 'Ball should have bounced LEFT');
  assert.strictEqual(state.ball.vy, 0, 'Ball vy should not have changed');
});

test('D4: Ghost Collision - Ball should not pass through the seam of two bricks', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[BRICK_COLS]; // Brick below brick1

  // Position ball so it overlaps both bricks
  state.ball.x = brick1.x + BRICK_W / 2;
  state.ball.y = brick1.y + BRICK_H; 
  state.ball.vy = -100;

  frame(mockCtx, state);

  // If it bounces twice, vy will be -100 again.
  assert.ok(state.ball.vy > 0, 'Ball should have bounced DOWN (once)');
});

import test from 'node:test';
import assert from 'node:assert';
import { createState, frame, collides, WIDTH, HEIGHT, BRICK_W, BRICK_H, BRICK_TOP, BRICK_GAP, BRICK_COLS } from '../game/neon.js';

const mockCtx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  font: () => {},
  fillText: () => {}
};

test('D1: Ball should bounce off a brick (currently plows through)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y + BRICK_H + 2;
  state.ball.vx = 0;
  state.ball.vy = -100; // Moving UP

  frame(mockCtx, state);

  assert.strictEqual(brick.alive, false);
  assert.ok(state.ball.vy > 0, 'Ball should have bounced DOWN');
});

test('D2: Ball should bounce off the SIDE of a brick (discriminate naive vy flip)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  state.ball.x = brick.x - 2;
  state.ball.y = brick.y + BRICK_H / 2;
  state.ball.vx = 100;
  state.ball.vy = 0;

  frame(mockCtx, state);

  assert.strictEqual(brick.alive, false);
  assert.ok(state.ball.vx < 0, 'Ball should have bounced LEFT');
  assert.strictEqual(state.ball.vy, 0, 'Ball vy should not have changed');
});

test('D3: Tunneling - High speed ball should not pass through brick', () => {
  const state = createState(6); // Level 6: speed = 260 + 5*90 = 710 px/s
  const brick = state.bricks[0];

  // Position ball just above the brick
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - 10; 
  state.ball.vy = 1000; // Very fast moving DOWN

  // We simulate a step of 0.05s
  state.ball.y += state.ball.vy * 0.05; // y = brick.y - 10 + 50 = brick.y + 40
  // The ball has now jumped from above to below the brick (brick.y + 20)

  frame(mockCtx, state);

  // In a simple AABB check, it's now below, so it didn't collide.
  // A proper system would detect it crossed the brick.
  assert.strictEqual(brick.alive, false, 'Brick should be destroyed even if ball tunneled through');
});

test('D4: Ghost Collision - Ball should not pass through the seam of two bricks', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[BRICK_COLS];

  state.ball.x = brick1.x + BRICK_W / 2;
  state.ball.y = brick1.y + BRICK_H; 
  state.ball.vy = -100;

  frame(mockCtx, state);

  assert.ok(state.ball.vy > 0, 'Ball should have bounced DOWN (once)');
});

test('D5: Collant - Ball should be pushed out of the brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y + 5; // Deep inside
  state.ball.vy = -100;

  frame(mockCtx, state);

  // After resolution, the ball should not be overlapping the brick anymore
  // If the brick is destroyed, this test is trivial. Let's make the brick stay alive for the test
  // or check if it's positioned correctly.

  // Let's assume the brick is destroyed. We still want the ball to be OUTSIDE.
  const stillCollides = collides(state.ball, brick);
  assert.strictEqual(stillCollides, false, 'Ball should be repositioned outside the brick');
});

# Playtest: La balle traverse les briques

## D1 — Absence de rebond
- **Famille** : face vs coin
- **Symptôme joueur** : la balle traverse les briques
- **Cause** : `game/neon.js:166` — la détection de collision ne déclenche aucune modification de la vélocité de la balle.
- **Invariant violé** : Tout contact avec une brique doit entraîner un rebond.
- **Déclencheur** : N'importe quelle collision balle/brique.
- **Attendu** : `vy` doit être inversé lors d'un impact horizontal, `vx` lors d'un impact vertical.
- **Référence** : https://learnopengl.com/In-Practice/2D-collision-resolution — La résolution de collision doit modifier la trajectoire.
- **Cas test** :
  ```js
  test('D1: Ball should bounce off a brick', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + BRICK_W / 2;
    state.ball.y = brick.y + BRICK_H + 2;
    state.ball.vx = 0; state.ball.vy = -100;
    frame(mockCtx, state);
    assert.ok(state.ball.vy > 0);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced DOWN`
- **Discrimine** : Une correction qui ne ferait que détruire la brique.
- **Vert quand** : La balle repart dans la direction opposée à l'impact.

## D2 — Mauvaise face de rebond (Correction Naïve)
- **Famille** : face vs coin
- **Symptôme joueur** : la balle rebondit bizarrement sur les côtés des briques.
- **Cause** : `game/neon.js:166` — absence de détermination de la face impactée.
- **Invariant violé** : Le rebond doit se faire sur l'axe perpendiculaire à la face touchée.
- **Déclencheur** : Collision sur le bord latéral d'une brique.
- **Attendu** : `vx` inversé, `vy` inchangé.
- **Référence** : https://learnopengl.com/In-Practice/2D-collision-resolution — Utilisation de la pénétration minimale pour déterminer l'axe de rebond.
- **Cas test** :
  ```js
  test('D2: Ball should bounce off the SIDE of a brick', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x - 2;
    state.ball.y = brick.y + BRICK_H / 2;
    state.ball.vx = 100; state.ball.vy = 0;
    frame(mockCtx, state);
    assert.ok(state.ball.vx < 0);
    assert.strictEqual(state.ball.vy, 0);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced LEFT`
- **Discrimine** : La correction naïve qui inverserait systématiquement `vy`.
- **Vert quand** : Le rebond est correct sur les 4 faces.

## D3 — Traversée (Tunneling)
- **Famille** : traversée
- **Symptôme joueur** : la balle passe à travers les briques à très haute vitesse.
- **Cause** : `game/neon.js:166` — détection discrète basée sur le recouvrement instantané.
- **Invariant violé** : Aucun obstacle ne doit être franchi sans rebond, quel que soit le pas de temps.
- **Déclencheur** : `ballSpeed(level) * dt > (BRICK_H + 2 * BALL_R)` (env. niveau 6+).
- **Attendu** : La brique est détruite et la balle rebondit même si elle a "sauté" par-dessus la brique entre deux frames.
- **Référence** : *Swept AABB* ou *Continuous Collision Detection (CCD)*.
- **Cas test** :
  ```js
  test('D3: Tunneling', () => {
    const state = createState(6);
    const brick = state.bricks[0];
    state.ball.x = brick.x + BRICK_W / 2;
    state.ball.y = brick.y - 10; 
    state.ball.vy = 1000;
    state.ball.y += state.ball.vy * 0.05; // Tunneling!
    frame(mockCtx, state);
    assert.strictEqual(brick.alive, false);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Brick should be destroyed even if ball tunneled through`
- **Discrimine** : La détection de collision discrète simple.
- **Vert quand** : La collision est détectée via balayage (sweeping) ou interpolation.

## D4 — Double Inversion (Ghost Collision)
- **Famille** : double inversion
- **Symptôme joueur** : la balle traverse la couture entre deux briques.
- **Cause** : `game/neon.js:166` — boucle sur toutes les briques sans limiter à un seul rebond par frame.
- **Invariant violé** : Un seul rebond par passe et par axe.
- **Déclencheur** : Balle touchant exactement la jointure de deux briques.
- **Attendu** : Un seul rebond est appliqué.
- **Référence** : *Tile seam ghost collision* resolution.
- **Cas test** :
  ```js
  test('D4: Ghost Collision', () => {
    const state = createState(1);
    const brick1 = state.bricks[0];
    const brick2 = state.bricks[BRICK_COLS];
    state.ball.x = brick1.x + BRICK_W / 2;
    state.ball.y = brick1.y + BRICK_H; 
    state.ball.vy = -100;
    frame(mockCtx, state);
    assert.ok(state.ball.vy > 0);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced DOWN (once)`
- **Discrimine** : La correction qui boucle et inverse la vélocité pour chaque brique touchée.
- **Vert quand** : Le premier rebond valide bloque les suivants pour la même frame.

## D5 — Effet Collant (Sinking/Sticking)
- **Famille** : collant
- **Symptôme joueur** : la balle vibre ou reste coincée dans la brique.
- **Cause** : `game/neon.js:166` — inversion de vitesse sans repositionnement.
- **Invariant violé** : Après résolution, la balle doit être hors du rectangle.
- **Déclencheur** : Collision profonde où `vy` inversé ne suffit pas à sortir la balle du rectangle au tour suivant.
- **Attendu** : la balle est repositionnée sur le bord de la brique.
- **Référence** : *Collision resolution by projection*.
- **Cas test** :
  ```js
  test('D5: Collant', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + BRICK_W / 2;
    state.ball.y = brick.y + 5;
    state.ball.vy = -100;
    frame(mockCtx, state);
    assert.strictEqual(collides(state.ball, brick), false);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should be repositioned outside the brick`
- **Discrimine** : La correction qui se contente d'inverser la vélocité.
- **Vert quand** : La balle ne recouvre plus la brique après le rebond.

