import test from 'node:test';
import assert from 'node:assert';
import { createState, frame, collides, WIDTH, HEIGHT, BRICK_W, BRICK_H, BRICK_TOP, BRICK_GAP, BRICK_COLS } from '../game/neon.js';

const mockCtx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  font: () => {},
  fillText: () => {}
};

test('D1: Ball should bounce off a brick (currently plows through)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y + BRICK_H + 2;
  state.ball.vx = 0;
  state.ball.vy = -100; // Moving UP

  frame(mockCtx, state);

  console.log('D1 ball.vy:', state.ball.vy);
  assert.ok(state.ball.vy > 0, 'Ball should have bounced DOWN');
});

test('D2: Ball should bounce off the SIDE of a brick (discriminate naive vy flip)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  state.ball.x = brick.x - 2;
  state.ball.y = brick.y + BRICK_H / 2;
  state.ball.vx = 100;
  state.ball.vy = 0;

  frame(mockCtx, state);

  console.log('D2 ball.vx:', state.ball.vx);
  assert.ok(state.ball.vx < 0, 'Ball should have bounced LEFT');
  assert.strictEqual(state.ball.vy, 0, 'Ball vy should not have changed');
});

test('D3: Tunneling - High speed ball should not pass through brick', () => {
  const state = createState(6); 
  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - 10; 
  state.ball.vy = 1000; 
  state.ball.y += state.ball.vy * 0.05;

  frame(mockCtx, state);

  assert.strictEqual(brick.alive, false, 'Brick should be destroyed even if ball tunneled through');
});

test('D4: Ghost Collision - Ball should not pass through the seam of two bricks', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[BRICK_COLS];

  state.ball.x = brick1.x + BRICK_W / 2;
  state.ball.y = brick1.y + BRICK_H; 
  state.ball.vy = -100;

  frame(mockCtx, state);

  console.log('D4 ball.vy:', state.ball.vy);
  assert.ok(state.ball.vy > 0, 'Ball should have bounced DOWN (once)');
});

test('D5: Collant - Ball should be pushed out of the brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y + 5;
  state.ball.vy = -100;

  frame(mockCtx, state);

  const stillCollides = collides(state.ball, brick);
  assert.strictEqual(stillCollides, false, 'Ball should be repositioned outside the brick');
});

