if (collides(state.ball, brick)) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  // Collision resolution: find the axis of minimum penetration
  const dx1 = state.ball.x + state.ball.r - brick.x; // overlap left
  const dx2 = brick.x + brick.w - (state.ball.x - state.ball.r); // overlap right
  const dy1 = state.ball.y + state.ball.r - brick.y; // overlap top
  const dy2 = brick.y + brick.h - (state.ball.y - state.ball.r); // overlap bottom

  const min = Math.min(dx1, dx2, dy1, dy2);

  if (min === dx1) {
    state.ball.vx = -Math.abs(state.ball.vx);
    state.ball.x = brick.x - state.ball.r;
  } else if (min === dx2) {
    state.ball.vx = Math.abs(state.ball.vx);
    state.ball.x = brick.x + brick.w + state.ball.r;
  } else if (min === dy1) {
    state.ball.vy = -Math.abs(state.ball.vy);
    state.ball.y = brick.y - state.ball.r;
  } else {
    state.ball.vy = Math.abs(state.ball.vy);
    state.ball.y = brick.y + brick.h + state.ball.r;
  }
  break;
}

