// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const oldX = ball.x;
  const oldY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0;
  }

  // Brick collisions
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    // Tunneling detection: check if the ball's path crossed the brick
    const tunneled = (
      Math.min(oldX, ball.x) - ball.r < brick.x + brick.w &&
      Math.max(oldX, ball.x) + ball.r > brick.x &&
      Math.min(oldY, ball.y) - ball.r < brick.y + brick.h &&
      Math.max(oldY, ball.y) + ball.r > brick.y
    );

    if (collides(ball, brick) || tunneled) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      const dx1 = ball.x + ball.r - brick.x;
      const dx2 = brick.x + brick.w - (ball.x - ball.r);
      const dy1 = ball.y + ball.r - brick.y;
      const dy2 = brick.y + brick.h - (ball.y - ball.r);
      const min = Math.min(dx1, dx2, dy1, dy2);

      if (min === dx1) {
        ball.vx = -Math.abs(ball.vx);
        ball.x = brick.x - ball.r;
      } else if (min === dx2) {
        ball.vx = Math.abs(ball.vx);
        ball.x = brick.x + brick.w + ball.r;
      } else if (min === dy1) {
        ball.vy = -Math.abs(ball.vy);
        ball.y = brick.y - ball.r;
      } else {
        ball.vy = Math.abs(ball.vy);
        ball.y = brick.y + brick.h + ball.r;
      }
      break; 
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

